/**
 * Deterministic constraint rules (brief §6.4). The UI uses them to disable options with a
 * stated reason, and the edit flow checks them before anything is sent to render — a
 * blocked change never consumes API units.
 */
import {
  FINISHES_BY_ZONE,
  SHINY_FINISHES,
  type Constraint,
  type Finish,
  type Kit,
  type LookRecipe,
  type Zone,
  type ZoneIntensity,
  type ZoneRecipe,
} from './types.js';

/** Max zone intensity allowed for lips under `discreetLips`. */
export const DISCREET_LIPS_MAX: ZoneIntensity = 2;

/** Pairs that cannot be active together. Empty today; kept so the chip UI has one source of truth. */
const CONFLICTS: readonly [Constraint, Constraint][] = [];

export function conflictsWith(active: Constraint[], candidate: Constraint): Constraint | null {
  for (const [a, b] of CONFLICTS) {
    if (candidate === a && active.includes(b)) return b;
    if (candidate === b && active.includes(a)) return a;
  }
  return null;
}

export function toggleConstraint(active: Constraint[], c: Constraint): Constraint[] {
  if (active.includes(c)) return active.filter((x) => x !== c);
  if (conflictsWith(active, c)) return active;
  return [...active, c];
}

export function isZoneAllowed(zone: Zone, constraints: Constraint[]): boolean {
  return !(zone === 'eyes' && constraints.includes('noShadow'));
}

export function isFinishAllowed(finish: Finish, constraints: Constraint[]): boolean {
  return !(constraints.includes('noShine') && SHINY_FINISHES.includes(finish));
}

export function allowedFinishes(zone: Zone, constraints: Constraint[]): Finish[] {
  return FINISHES_BY_ZONE[zone].filter((f) => isFinishAllowed(f, constraints));
}

export function maxIntensity(zone: Zone, constraints: Constraint[]): ZoneIntensity {
  return zone === 'lips' && constraints.includes('discreetLips') ? DISCREET_LIPS_MAX : 5;
}

export type Violation =
  | { kind: 'zoneBlocked'; zone: Zone; constraint: 'noShadow' }
  | { kind: 'finishBlocked'; zone: Zone; finish: Finish; constraint: 'noShine' }
  | { kind: 'intensityTooHigh'; zone: Zone; max: ZoneIntensity; constraint: 'discreetLips' }
  | { kind: 'notInKit'; zone: Zone; shadeId: string };

/** Every rule a single zone breaks. Empty array = valid. */
export function zoneViolations(
  zone: Zone,
  z: ZoneRecipe,
  constraints: Constraint[],
  kit: Kit,
): Violation[] {
  const out: Violation[] = [];
  if (!z.enabled) return out;
  if (!isZoneAllowed(zone, constraints)) out.push({ kind: 'zoneBlocked', zone, constraint: 'noShadow' });
  if (!isFinishAllowed(z.finish, constraints))
    out.push({ kind: 'finishBlocked', zone, finish: z.finish, constraint: 'noShine' });
  const max = maxIntensity(zone, constraints);
  if (z.intensity > max) out.push({ kind: 'intensityTooHigh', zone, max, constraint: 'discreetLips' });
  // A declared kit item is a shade in the finish the person owns: both must match.
  if (kit.status === 'declared' && !kit.items[zone].some((i) => i.shadeId === z.shadeId && i.finish === z.finish))
    out.push({ kind: 'notInKit', zone, shadeId: z.shadeId });
  return out;
}

export function recipeViolations(r: LookRecipe, constraints: Constraint[], kit: Kit): Violation[] {
  return (['eyes', 'lips', 'cheeks'] as const).flatMap((zone) =>
    zoneViolations(zone, r[zone], constraints, kit),
  );
}

/** Kit items the constraints make unusable (e.g. a gloss lipstick under "no shine"). */
export function kitItemBlocked(finish: Finish, constraints: Constraint[]): boolean {
  return !isFinishAllowed(finish, constraints);
}
